/// 🚪️ This subset's complete io declaration — the native `LanguagePair`s and `ArtifactCodec` plus
/// the twelve typed foreign entries. `pilot_languages()` indices are fixed by that function's own
/// literal `vec![document, op, diff, pack, spr]` order, the same role→slot mapping `🗒️note`'s
/// `io()` uses.
pub fn io() -> semio_framework_plugin::app::declarations::IoDeclaration {
    use crate::standards::v1::subsets::any::io::export::serializers::artifacts as export;
    use crate::standards::v1::subsets::any::io::import::deserializers::artifacts as import;
    use crate::{Block2dMutation, Block2dSnapshot, BLOCK2D_DIALECT, BLOCK_2D_SCHEMA};
    use semio_framework::io::io_mechanism::{deserializer_entry, serializer_entry, IoEntry};
    use semio_framework_plugin::app::declarations::{IoDeclaration, LanguagePair, NativeCodecs};
    use std::sync::OnceLock;

    /// 🎹️ One vtable row per typed leaf, both directions per format — the single place this subset
    /// advertises what it can and cannot convert.
    fn entries() -> &'static [IoEntry] {
        static ENTRIES: OnceLock<Vec<IoEntry>> = OnceLock::new();
        ENTRIES
            .get_or_init(|| {
                vec![
                    serializer_entry::<Block2dSnapshot, export::txt::v_utf_8::any::Block2dIntoTxt>(BLOCK2D_DIALECT),
                    deserializer_entry::<Block2dSnapshot, import::txt::v_utf_8::any::TxtIntoBlock2d>(BLOCK2D_DIALECT),
                    serializer_entry::<Block2dSnapshot, export::json::v_rfc8259::any::Block2dIntoJson>(BLOCK2D_DIALECT),
                    deserializer_entry::<Block2dSnapshot, import::json::v_rfc8259::any::JsonIntoBlock2d>(BLOCK2D_DIALECT),
                    serializer_entry::<Block2dSnapshot, export::zip::v2_0::any::Block2dIntoZip>(BLOCK2D_DIALECT),
                    deserializer_entry::<Block2dSnapshot, import::zip::v2_0::any::ZipIntoBlock2d>(BLOCK2D_DIALECT),
                ]
            })
            .as_slice()
    }

    let langs = crate::pilot_languages();
    IoDeclaration {
        native: NativeCodecs {
            snapshot: LanguagePair { text: Some(&langs[0]), binary: Some(&langs[3]) },
            diff: LanguagePair { text: Some(&langs[2]), binary: None },
            mutations: LanguagePair { text: Some(&langs[1]), binary: Some(&langs[4]) },
            inferences: None,
            codec: store::ArtifactCodec::bare::<Block2dSnapshot, Block2dMutation>(BLOCK_2D_SCHEMA.to_string()),
        },
        entries: entries(),
    }
}
