    let widths = r#"{"block2_document":2,"block2_kind":9,"block2_presentation":14,"block2_handle_kind":8,"block2_handle":11,"block2_compatibility":7,"block2_attribute":6,"block2_author":6,"block2_camera2d":11,"block2_meta":3}"#;
