//! 🔺️ Diff for `AddAttribute`.

use crate::Block2dSnapshot;
use crate::standards::v1::subsets::any::schema::diff::{Block2dAttributesDelta, Block2dDiff};

//#region 🔖️Diff
pub fn diff(payload: &super::AddAttribute, base: &Block2dSnapshot) -> protocol::MutationOutcome<Block2dDiff> {
    if base.attributes.iter().any(|item| item.key == payload.attribute.key) {
        return protocol::MutationOutcome::new(Block2dDiff::default())
            .absorb_messages([protocol::MutationMessage::warning("mutation.no-op", format!("{} \"{}\" already present", "attribute", payload.attribute.key)).at(vec![payload.attribute.key.clone()])]);
    }
    protocol::MutationOutcome::new(Block2dDiff { attributes: Some(Block2dAttributesDelta { added: vec![payload.attribute.clone()], ..Default::default() }), ..Default::default() })
}
//#endregion 🔖️Diff

//! 🔺️ Diff for `DeleteHandleKind`.

use crate::Block2dSnapshot;
use crate::standards::v1::subsets::any::schema::diff::{Block2dDiff, Block2dHandleKindsDelta};

//#region 🔖️Diff
pub fn diff(payload: &super::DeleteHandleKind, base: &Block2dSnapshot) -> protocol::MutationOutcome<Block2dDiff> {
    if !base.handle_kinds.iter().any(|item| item.id == payload.id) {
        return protocol::MutationOutcome::error("mutation.target-missing", format!("{} \"{}\" not found", "handle-kind", payload.id), vec![payload.id.clone()]);
    }
    protocol::MutationOutcome::new(Block2dDiff { handle_kinds: Some(Block2dHandleKindsDelta { removed: vec![payload.id.clone()], ..Default::default() }), ..Default::default() })
}
//#endregion 🔖️Diff

//! 🔺️ Diff for `RenameNodeKind`.

use crate::BlockKindIdentity;
use crate::Block2dSnapshot;
use crate::standards::v1::subsets::any::schema::diff::Block2dDiff;

//#region 🔖️Diff
pub fn diff(payload: &super::RenameNodeKind, base: &Block2dSnapshot) -> protocol::MutationOutcome<Block2dDiff> {
    // 🪪️ `node_kind` is the document's single root kind (not a catalog member addressed by id), so
    // there is no missing-target case and no collection to collide with — only the no-op check applies.
    if payload.new_name == base.node_kind.name {
        return protocol::MutationOutcome::empty().warning("mutation.no-op", format!("Node kind name is already \"{}\".", payload.new_name));
    }
    protocol::MutationOutcome::new(Block2dDiff { node_kind: Some(BlockKindIdentity { name: payload.new_name.clone(), ..base.node_kind.clone() }), ..Default::default() })
}
//#endregion 🔖️Diff

